package main
import("encoding/json";"fmt";"net/http/httptest";"strings";"regexp";"github.com/Azpect3120/Web-Database-Viewer/internal/database";"github.com/Azpect3120/Web-Database-Viewer/internal/templates";"github.com/gin-contrib/sessions";"github.com/gin-contrib/sessions/cookie";"github.com/gin-gonic/gin")
func main(){gin.SetMode(gin.TestMode); name:="B & <猫>"; url:="file:synthetic-url-password?mode=memory&cache=shared"; m:=map[string][2]string{name:{url,"sqlite3"}}; option:=templates.ConnectionsList(m,name); re:=regexp.MustCompile(`data-query-history-id="([a-f0-9]{64})"`); match:=re.FindStringSubmatch(option); r:=gin.New();r.Use(sessions.Sessions("test",cookie.NewStore([]byte("01234567890123456789012345678901"))));r.Use(func(c *gin.Context){b,_:=json.Marshal(m);s:=sessions.Default(c);s.Set("connections",b);s.Set("current",name);c.Next()});r.POST("/",database.QueryCurrent);w:=httptest.NewRecorder();req:=httptest.NewRequest("POST","/",strings.NewReader("sql=select+%27synthetic-result-sentinel%27"));req.Header.Set("Content-Type","application/x-www-form-urlencoded");r.ServeHTTP(w,req);h:=w.Header().Get("X-Query-History-Connection");if len(match)!=2||match[1]!=h||strings.Contains(h,"synthetic")||!strings.Contains(w.Body.String(),"synthetic-result-sentinel"){panic("identity or synthetic result check failed")};fmt.Println("PASS real ConnectionsList option equals real QueryCurrent header, 64 hex; synthetic URL/password/driver absent; synthetic result observed")}
